def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # outcome counts
    cc = cd = dc = dd = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if b == 'C':
                dc += 1
            else:
                dd += 1

    opp_c = cc + dc
    opp_d = n - opp_c
    me_c = cc + cd
    me_d = n - me_c

    last_me = me[-1]
    last_opp = opp[-1]

    # Recent window
    w = 12 if n >= 12 else n
    start = n - w
    rec_opp_c = 0
    rec_opp_d = 0
    rec_me_d = 0
    for i in range(start, n):
        a, b = history[i]
        if b == 'C':
            rec_opp_c += 1
        else:
            rec_opp_d += 1
        if a == 'D':
            rec_me_d += 1

    # Near-end exploitation of non-retaliators
    if n >= 88:
        if opp_d == 0:
            return 'D'
        if opp_d <= 2 and rec_opp_d <= 1:
            return 'D'

    # Persistent defector detection
    if rec_opp_d >= w - 1 and n >= 6:
        # probe rarely to see if they change, otherwise defect
        if last_opp == 'C':
            return 'C' if rng.random() < 0.6 else 'D'
        return 'D'

    # All-cooperator opponent: exploit moderately but keep most cooperation
    if opp_d == 0:
        if n < 10:
            return 'C'
        if n >= 80:
            return 'D' if rng.random() < 0.8 else 'C'
        if n >= 50:
            return 'D' if rng.random() < 0.25 else 'C'
        return 'C'

    # All-defector opponent: protect
    if opp_c == 0:
        if n >= 4 and n < 10 and rng.random() < 0.3:
            return 'C'
        if n >= 10 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # If opponent has been very cooperative recently, reciprocate
    if rec_opp_d == 0 and n >= 6:
        if rec_me_d >= 3:
            return 'C'
        if n >= 70 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Escape mutual defection spiral
    if rec_opp_d >= 5 and rec_me_d >= 4:
        if rng.random() < 0.7:
            return 'C'

    # Reward last cooperation
    if last_opp == 'C':
        if last_me == 'D':
            # We just exploited; sometimes continue, sometimes restore trust
            if n < 20:
                return 'C'
            if dc >= 2 and n >= 8:
                if rng.random() < 0.5:
                    return 'D'
            return 'C'
        if n >= 75 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Opponent defected last
    if rec_opp_c >= 7:
        # Forgive occasionally if overall cooperative
        if rng.random() < 0.4:
            return 'C'
        return 'D'
    if last_me == 'D':
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    return 'D'
